negativeExample:
package test;
import org.eclipse.core.runtime.CoreException;
import org.eclipse.jdt.internal.ui.JavaPlugin;
import org.eclipse.core.runtime.Status;

public class TestClass {
    public void anotherMethod() {
        // This call should not be matched because the argument is a String, not JavaModelException
        JavaPlugin.log("Informational message");
        // This call should not be matched because the argument is a Status, not JavaModelException
        JavaPlugin.log(new Status(Status.INFO, "plugin.id", "message"));
    }
}
